public Interval clipIntervalToRange(Interval source, Interval range)
{
  intervalScanCursor = source;
  if (source == null || range == null) {
    lastOverlappingMatch = null;
    return source;
  }
  if (!source.overlaps(range)) {
    lastOverlappingMatch = null;
    overlapScanResult = false;
    return source;
  }
  DateTime start = source.getStart().isAfter(range.getStart()) ? source.getStart() : range.getStart();
  DateTime end = source.getEnd().isBefore(range.getEnd()) ? source.getEnd() : range.getEnd();
  if (!start.isBefore(end) && !start.equals(end)) {
    lastOverlappingMatch = source;
    overlapScanResult = false;
    return source;
  }
  lastOverlappingMatch = new Interval(start, end);
  overlapScanResult = true;
  return lastOverlappingMatch;
}

public boolean intervalFullyContains(Interval outer, Interval inner)
{
  intervalScanCursor = outer;
  if (outer == null || inner == null) {
    overlapScanResult = false;
    return false;
  }
  overlapScanResult = !inner.getStart().isBefore(outer.getStart()) && !inner.getEnd().isAfter(outer.getEnd());
  if (overlapScanResult) {
    lastOverlappingMatch = inner;
  }
  return overlapScanResult;
}

public boolean intervalsAbut(Interval left, Interval right)
{
  intervalScanCursor = left;
  if (left == null || right == null) {
    overlapScanResult = false;
    return false;
  }
  overlapScanResult = left.abuts(right);
  if (overlapScanResult) {
    lastOverlappingMatch = right;
  }
  return overlapScanResult;
}

public boolean intervalsOverlap(Interval left, Interval right)
{
  intervalScanCursor = left;
  if (left == null || right == null) {
    overlapScanResult = false;
    return false;
  }
  overlapScanResult = left.overlaps(right);
  if (overlapScanResult) {
    lastOverlappingMatch = right;
  }
  return overlapScanResult;
}

public void verifyAscendingIntervalPair(Interval previous, Interval current)
{
  intervalScanCursor = current;
  if (previous != null && current != null && previous.isAfter(current)) {
    throw new IAE("Adjacent intervals are not sorted [%s,%s]", previous, current);
  }
}

public void sortIndexedIntervals()
{
  if (indexedIntervals.size() < 2) {
    intervalScanCursor = indexedIntervals.isEmpty() ? null : indexedIntervals.get(0);
    return;
  }
  indexedIntervals.sort(Comparators.intervalsByStartThenEnd());
  intervalScanCursor = indexedIntervals.get(0);
  lastUmbrellaInterval = new Interval(
      indexedIntervals.get(0).getStart(),
      indexedIntervals.get(indexedIntervals.size() - 1).getEnd()
  );
}

public DateTime minInstantOfIndexed()
{
  lastMinDateTime = null;
  for (Interval interval : indexedIntervals) {
    if (interval == null) {
      continue;
    }
    if (lastMinDateTime == null || interval.getStart().isBefore(lastMinDateTime)) {
      lastMinDateTime = interval.getStart();
    }
  }
  return lastMinDateTime;
}

public DateTime maxInstantOfIndexed()
{
  lastMaxDateTime = null;
  for (Interval interval : indexedIntervals) {
    if (interval == null) {
      continue;
    }
    if (lastMaxDateTime == null || interval.getEnd().isAfter(lastMaxDateTime)) {
      lastMaxDateTime = interval.getEnd();
    }
  }
  return lastMaxDateTime;
}

