public static List<Interval> condenseIntervals(Iterable<Interval> intervals)
{
  final SortedSet<Interval> sortedIntervals;

  if (intervals instanceof SortedSet) {
    final SortedSet<Interval> theSortedIntervals = (SortedSet<Interval>) intervals;

    // The set is only usable as-is if it is sorted in ascending order by interval start (and end, as a
    // tiebreaker). Otherwise, recreate it with a comparator that provides that order.
    if (isSortedByStartThenEnd(theSortedIntervals)) {
      sortedIntervals = theSortedIntervals;
    } else {
      sortedIntervals = new TreeSet<>(Comparators.intervalsByStartThenEnd());
      sortedIntervals.addAll(theSortedIntervals);
    }
  } else {
    sortedIntervals = new TreeSet<>(Comparators.intervalsByStartThenEnd());
    for (Interval interval : intervals) {
      sortedIntervals.add(interval);
    }
  }

  // Zero-length intervals do not represent any time, so they should not be returned.
  return ImmutableList.copyOf(
      Iterators.filter(
          condensedIntervalsIterator(sortedIntervals.iterator()),
          interval -> !interval.isEmpty()
      )
  );
}

